head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > getRangeXML]<br/>Row 의 인덱스값을 사용하여 특정 범위의 Row 데이터를 XML 객체로 반환합니다.",
    "validation" : [
        "from(필수) 파라미터로 반환 받으려는 Row 데이터의 시작 인덱스값을 숫자로 설정합니다.",
        "to(필수) 파라미터로 반환 받으려는 Row 데이터의 마지막 인덱스값을 숫자로 설정합니다.",
        "Row 의 인덱스는 0 부터 시작하며 필터링/정렬 설정에 맞게 인덱스를 설정합니다.",
        "반환값으로 Row 의 상태값에 관계없이 필터링된 Row 데이터의 파라미터 범위를 XML 객체로 반환합니다.",
        "DataList 모듈에 필터가 적용되지 않은 경우 전체 Row 데이터의 파라미터 범위를 XML 객체로 반환합니다.",
        "XML 은 인덱스값이 작은 Row 부터 큰 Row 순서로 생성됩니다.",
        "반환된 객체의 xml 속성값은 baseNode 속성값이 최상위 태그명으로 적용되고, 반복되는 데이터 태그엔 repeatNode 속성값이 적용됩니다.",
        "데이터 태그는 index 속성으로 Row 의 인덱스값이 설정되며, 'E' 상태인 Row 는 'removed' 값이 설정됩니다.",
        "데이터 태그는 'rowStatus' 를 마지막 하위 태그로 Row 의 상태값이 설정되며 'statusValue' 속성으로 상태코드값이 설정됩니다.",
        "from, to 파라미터값이 Row 의 인덱스값이 아니어도 범위가 유효하다면 getRangeArray() 메소드는 동작합니다.",
        "from, to 파라미터값의 범위가 유효하지 않으면 Column 의 ID 정보와 빈 데이터 배열을 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');

    scwin.btn_insertRow_onclick();
    scwin.btn_deleteRow_onclick();
    scwin.btn_setCellData_onclick();
    scwin.btn_removeRow_onclick();
}   



scwin.btn_insertRow_onclick = function (e) {
    let insertIndex = target1.insertRow();
    target1.setRowData(insertIndex,["insert1","insert2","insert3","insert4"],true);
};



scwin.btn_deleteRow_onclick = function (e) {
    target1.deleteRow(0);
};



scwin.btn_setCellData_onclick = function (e) {
    target1.setCellData(2, "col1", "change");
};



scwin.btn_removeRow_onclick = function (e) {
    target1.removeRow(3);
}



scwin.btn_setColumnFilter_onclick = function (e) {
	target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_2", condition:'and'})    
    target1.setColumnFilter( {type:'row', colIndex:'col1', key:"insert1", condition:'or'})
};



scwin.btn_sort_onclick = function (e) {
    target1.sort("col1", 1);
};



scwin.btn_getRangeXML_onclick = function (e) {
    let rtn = '';
    let nFrom = par_from.getText();
    let nTo = par_to.getText();

    rtn = target1.getRangeXML(Number(nFrom), Number(nTo));

    const serializer = new XMLSerializer();
    let xmlString = serializer.serializeToString(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result: " + rtn);
    wf_body_bottom.getObj("scwin").setReturnValue("result.xml: " + xmlString);
};
